/**
 * Builds `dist/curriculum.html` from CONTENT-NG.md, CONTENT-UK.md and CONTENT-US.md.
 *
 * Rendered at build time rather than written by hand, and that is the whole
 * point of it. The coverage tables in those files are regenerated by
 * `npm run content:track` straight from the packs, so a page built from them
 * cannot claim a class has content when it does not. A hand-written page would
 * be accurate for about a week.
 *
 * The markdown here is ours and its shape is known — headings, tables, lists,
 * blockquotes, a little inline formatting — so this is a focused renderer rather
 * than a markdown library. Anything it does not recognise is escaped and shown
 * as a paragraph, which fails visibly instead of silently dropping content.
 */

import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

const PACKS = [
  { file: 'CONTENT-NG.md', id: 'nigerian', flag: '🇳🇬', name: 'Nigerian', sub: 'UBE · Basic 1–6' },
  { file: 'CONTENT-UK.md', id: 'british', flag: '🇬🇧', name: 'British', sub: 'National Curriculum · Years 1–6' },
  { file: 'CONTENT-US.md', id: 'american', flag: '🇺🇸', name: 'American', sub: 'Common Core · Kindergarten–Grade 5' },
]

const esc = (s) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c])

/** Inline formatting. `<br>` is the one raw tag the trackers use, so it survives. */
function inline(text) {
  return esc(text)
    .replace(/&lt;br ?\/?&gt;/g, '<br />')
    .replace(/`([^`]+)`/g, (_, code) => `<code>${code}</code>`)
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" rel="noopener">$1</a>')
}

const cells = (row) =>
  row
    .replace(/^\||\|$/g, '')
    .split('|')
    .map((c) => c.trim())

/**
 * Markdown to HTML, for the subset these files use.
 *
 * Written as a line machine rather than a set of regexes over the whole
 * document, because tables and lists need to know where they end.
 */
function render(markdown) {
  const lines = markdown.split(/\r?\n/)
  const out = []
  let i = 0
  let para = []

  const flush = () => {
    if (para.length === 0) return
    out.push(`<p>${inline(para.join(' '))}</p>`)
    para = []
  }

  while (i < lines.length) {
    const line = lines[i]

    /* The generated-block markers are plumbing, not content. */
    if (line.startsWith('<!--')) {
      i += 1
      continue
    }

    if (line.trim() === '') {
      flush()
      i += 1
      continue
    }

    const heading = /^(#{1,4})\s+(.*)$/.exec(line)
    if (heading) {
      flush()
      /* Demoted one level: the page supplies its own h1 and h2 per pack, so a
         tracker's own h1 becomes an h3 and the hierarchy stays honest. */
      const level = Math.min(6, heading[1].length + 2)
      out.push(`<h${level}>${inline(heading[2])}</h${level}>`)
      i += 1
      continue
    }

    if (line.startsWith('> ')) {
      flush()
      const quote = []
      while (i < lines.length && lines[i].startsWith('> ')) {
        quote.push(lines[i].slice(2))
        i += 1
      }
      out.push(`<blockquote>${inline(quote.join(' '))}</blockquote>`)
      continue
    }

    /* A table: header row, alignment row, then body until a blank line. */
    if (line.startsWith('|') && /^\|[\s:|-]+\|$/.test(lines[i + 1] ?? '')) {
      flush()
      const head = cells(line)
      const align = cells(lines[i + 1]).map((a) => (a.endsWith(':') ? ' class="n"' : ''))
      i += 2
      const body = []
      while (i < lines.length && lines[i].startsWith('|')) {
        body.push(cells(lines[i]))
        i += 1
      }
      out.push(
        `<div class="scroll"><table><thead><tr>${head
          .map((h, n) => `<th${align[n] ?? ''}>${inline(h)}</th>`)
          .join('')}</tr></thead><tbody>${body
          .map(
            (row) =>
              `<tr>${row.map((c, n) => `<td${align[n] ?? ''}>${inline(c)}</td>`).join('')}</tr>`,
          )
          .join('')}</tbody></table></div>`,
      )
      continue
    }

    if (/^[-*]\s+/.test(line) || /^\d+\.\s+/.test(line)) {
      flush()
      const ordered = /^\d+\.\s+/.test(line)
      const items = []
      while (i < lines.length && (/^[-*]\s+/.test(lines[i]) || /^\d+\.\s+/.test(lines[i]))) {
        let item = lines[i].replace(/^([-*]|\d+\.)\s+/, '')
        i += 1
        /* Continuation lines are indented under their bullet. */
        while (i < lines.length && /^\s{2,}\S/.test(lines[i])) {
          item += ' ' + lines[i].trim()
          i += 1
        }
        items.push(`<li>${inline(item)}</li>`)
      }
      out.push(`<${ordered ? 'ol' : 'ul'}>${items.join('')}</${ordered ? 'ol' : 'ul'}>`)
      continue
    }

    para.push(line.trim())
    i += 1
  }
  flush()
  return out.join('\n')
}

/**
 * The headline numbers, pulled from the generated block.
 *
 * Read out of the rendered text rather than recomputed, so the summary at the
 * top of the page and the table below it can never disagree.
 */
function summarise(markdown) {
  const skills = /\*\*(\d+) skills\*\*/.exec(markdown)
  const subjects = /across (\d+) authored subjects?/.exec(markdown)
  const empty = /\*\*(\d+) of (\d+) classes have nothing at all:\*\*/.exec(markdown)
  return {
    skills: skills ? Number(skills[1]) : 0,
    subjects: subjects ? Number(subjects[1]) : 0,
    emptyClasses: empty ? Number(empty[1]) : 0,
    totalClasses: empty ? Number(empty[2]) : 6,
  }
}

export async function buildCurriculumPage({ root, dist }) {
  const packs = []
  for (const pack of PACKS) {
    const raw = await readFile(path.join(root, pack.file), 'utf8')
    /* The page gives each pack its own heading, so the tracker's h1 would only
       repeat it one size smaller. */
    const markdown = raw.replace(/^#\s+.*\r?\n/, '')
    packs.push({ ...pack, html: render(markdown), ...summarise(markdown) })
  }

  const updated = new Date().toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  })

  const cards = packs
    .map(
      (p) => `
        <a class="pack-card" href="#${p.id}">
          <span class="pack-flag">${p.flag}</span>
          <span class="pack-name">${p.name}</span>
          <span class="pack-count">${p.skills} skills</span>
          <span class="pack-note">${
            p.emptyClasses > 0
              ? `${p.emptyClasses} of ${p.totalClasses} classes still empty`
              : `all ${p.totalClasses} classes, ${p.subjects} subjects`
          }</span>
        </a>`,
    )
    .join('')

  const sections = packs
    .map(
      (p) => `
      <section id="${p.id}" class="pack">
        <div class="wrap">
          <h2><span aria-hidden="true">${p.flag}</span> ${p.name}</h2>
          <p class="pack-sub">${p.sub}</p>
          ${p.html}
          <p class="back"><a href="#top">Back to the top</a></p>
        </div>
      </section>`,
    )
    .join('')

  const html = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
    <title>What is actually in Brainy: curriculum coverage and changelog</title>
    <meta
      name="description"
      content="Every skill in every class of the Nigerian, British and American packs, counted from the app itself, with what is missing and what changed when."
    />
    <link rel="icon" type="image/svg+xml" href="/brand.svg" />
    <link rel="icon" sizes="32x32" href="/favicon.ico" />
    <meta name="theme-color" content="#7c3aed" />
    <link rel="canonical" href="https://brainy.fortbridge.app/curriculum.html" />
    <style>
      :root {
        --violet-50: #f5f3ff;
        --violet-100: #ede9fe;
        --violet-200: #ddd6fe;
        --violet-600: #7c3aed;
        --violet-700: #6d28d9;
        --violet-900: #4c1d95;
        --ink: #1e1b4b;
        --muted: #5b5580;
      }
      * { box-sizing: border-box; }
      html { scroll-behavior: smooth; }
      body {
        margin: 0;
        font-family: 'Nunito', 'Segoe UI Variable', 'Segoe UI', system-ui, -apple-system, sans-serif;
        color: var(--ink);
        background: #fff;
        line-height: 1.65;
        -webkit-font-smoothing: antialiased;
      }
      .wrap { width: min(880px, 100% - 2.5rem); margin-inline: auto; }
      a { color: var(--violet-700); }
      header.nav {
        border-bottom: 1px solid var(--violet-100);
        background: rgba(255, 255, 255, 0.9);
        position: sticky;
        top: 0;
        z-index: 5;
        backdrop-filter: blur(10px);
      }
      .nav-inner { display: flex; align-items: center; gap: 1rem; padding: 0.8rem 0; }
      .brand {
        display: flex; align-items: center; gap: 0.6rem; min-height: 44px;
        font-weight: 900; font-size: 1.25rem; color: var(--violet-900); text-decoration: none;
      }
      .brand img { width: 34px; height: 34px; border-radius: 8px; display: block; }
      .nav-inner .back-link { margin-left: auto; font-weight: 700; text-decoration: none; font-size: 0.95rem; }
      .hero { background: linear-gradient(180deg, var(--violet-50), #fff); padding: 3rem 0 2rem; }
      h1 { font-size: clamp(1.9rem, 4.5vw, 2.8rem); line-height: 1.15; margin: 0 0 0.6rem; letter-spacing: -0.02em; }
      .lede { color: var(--muted); font-weight: 600; font-size: 1.05rem; max-width: 40rem; }
      .updated { color: var(--muted); font-weight: 700; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.06em; }

      .packs { display: grid; gap: 0.75rem; grid-template-columns: 1fr; margin-top: 1.75rem; }
      @media (min-width: 700px) { .packs { grid-template-columns: repeat(3, 1fr); } }
      .pack-card {
        display: block; text-decoration: none; color: inherit; background: #fff;
        border: 2px solid var(--violet-200); border-radius: 18px; padding: 1rem 1.1rem;
      }
      .pack-card:hover { border-color: var(--violet-600); }
      .pack-flag { font-size: 1.6rem; display: block; line-height: 1; }
      .pack-name { display: block; font-weight: 900; margin-top: 0.35rem; }
      .pack-count { display: block; font-weight: 900; font-size: 1.5rem; color: var(--violet-700); letter-spacing: -0.02em; }
      .pack-note { display: block; color: var(--muted); font-weight: 600; font-size: 0.85rem; }

      section.pack { padding: 2.5rem 0; border-top: 1px solid var(--violet-100); }
      section.pack h2 { font-size: clamp(1.5rem, 3vw, 2rem); margin: 0 0 0.15rem; letter-spacing: -0.02em; }
      .pack-sub { color: var(--muted); font-weight: 700; margin: 0 0 1.5rem; }
      section.pack h3 { font-size: 1.25rem; margin: 2rem 0 0.5rem; }
      section.pack h4 { font-size: 1.05rem; margin: 1.5rem 0 0.4rem; }
      section.pack h5 { font-size: 0.95rem; margin: 1.1rem 0 0.3rem; color: var(--muted); }
      section.pack p { margin: 0 0 0.9rem; }
      section.pack ul, section.pack ol { margin: 0 0 1rem; padding-left: 1.3rem; }
      section.pack li { margin-bottom: 0.3rem; }
      blockquote {
        margin: 0 0 1rem; padding: 0.8rem 1rem; background: #fffbeb;
        border-left: 4px solid #f59e0b; border-radius: 0 12px 12px 0; font-weight: 700;
      }
      code {
        background: var(--violet-50); border: 1px solid var(--violet-100); border-radius: 6px;
        padding: 0.05rem 0.35rem; font-size: 0.88em;
        font-family: 'SFMono-Regular', Consolas, monospace;
      }
      .scroll { overflow-x: auto; margin: 0 0 1.25rem; }
      table { border-collapse: collapse; width: 100%; font-size: 0.92rem; }
      th, td { text-align: left; padding: 0.5rem 0.6rem; border-bottom: 1px solid var(--violet-100); white-space: nowrap; }
      th { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
      td.n, th.n { text-align: right; font-variant-numeric: tabular-nums; }
      tbody tr:last-child td { border-bottom: 0; }
      .back { font-weight: 700; }
      footer { border-top: 1px solid var(--violet-100); padding: 2rem 0 3rem; color: var(--muted); font-weight: 600; font-size: 0.9rem; }
      footer a { font-weight: 700; }
    </style>
  </head>
  <body id="top">
    <header class="nav">
      <div class="wrap nav-inner">
        <a class="brand" href="/"><img src="/brand.svg" alt="" width="34" height="34" />Brainy</a>
        <a class="back-link" href="/">← Back to the site</a>
      </div>
    </header>

    <div class="hero">
      <div class="wrap">
        <p class="updated">Updated ${updated}</p>
        <h1>What is actually in Brainy</h1>
        <p class="lede">
          Every skill in every class, counted from the app itself rather than written down by hand, so
          a gap shows up here as plainly as it would to your child. Where a class is empty, it says so.
          If you are choosing a curriculum, read the table for your child's class before you decide.
        </p>
        <div class="packs">${cards}</div>
      </div>
    </div>

    ${sections}

    <footer>
      <div class="wrap">
        <p>
          Coverage is regenerated from the packs themselves by <code>npm run content:track</code>, and this
          page is rebuilt from those files on every deploy. Nothing on it is typed twice.
        </p>
        <p><a href="/">Back to the site</a> · <a href="/privacy.html">Privacy notice</a> · <a href="/play/">Open Brainy</a></p>
      </div>
    </footer>
  </body>
</html>
`

  await writeFile(path.join(dist, 'curriculum.html'), html, 'utf8')
  return packs.map((p) => `${p.name} ${p.skills}`)
}
